compile.workshop:
variables {
    global:
        0: g
}

rule ("damage context calls") {
    event {
        Player Took Damage;
        All;
        All;
    }
    actions {
        Set Global Variable(g, Attacker);
        Set Global Variable(g, Victim);
        Set Global Variable(g, Event Player);
        Set Global Variable(g, Host Player);
        Set Global Variable(g, Local Player);
        Set Global Variable(g, Event Damage);
        Set Global Variable(g, Event Direction);
        Set Global Variable(g, Event Ability);
        Set Global Variable(g, Event Was Critical Hit);
        Set Global Variable(g, Event Was Environment);
        Set Global Variable(g, True);
        Set Global Variable(g, Null);
        Set Global Variable(g, True);
        Set Global Variable(g, False);
        If(Compare(Attacker, !=, Null));
            Set Move Speed(Event Player, 150);
    }
}

rule ("healing context calls") {
    event {
        Player Dealt Healing;
        All;
        All;
    }
    actions {
        Set Global Variable(g, Healer);
        Set Global Variable(g, Healee);
        Set Global Variable(g, Event Healing);
        Set Global Variable(g, Event Was Health Pack);
    }
}

